mapper.select:
select ft.T_Name as tName, ft.T_Code as tCode, mn.*, pm.Rpm_Type, pm.Rpm_Level, pm.Rpm_Points, pm.Rpm_Measure, pm.Rpm_Involved, pm.Rpm_Dep, pm.Rpm_Content, pm.Create_Uid, pm.Rpm_Icon, pm.Rpm_Icon_Color, pm.Rpm_Status from Risk_Template_Relation mn left join SYS_FileTemplate ft on ft.T_ID=mn.T_ID left join Risk_Prevention_Measure pm on pm.id=mn.Rpm_Id
and mn.Te_Id = #{params.teId}
and mn.Rpm_Id=#{params.rpmId}
and INSTR(mn.Rtr_Field_Name,#{params.rtrFieldName})
and INSTR(mn.Rtr_Field_Code,#{params.rtrFieldCode})
and INSTR( ft.T_Name,#{params.tName})
and INSTR(ft.T_Code,#{params.tCode})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
